use std::{fs,path::Path,collections::{BTreeMap,BTreeSet},process::Command};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-arithmetic-leaves-corrected";type Event=[u64;10];
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn median(mut xs:Vec<f64>)->f64{assert!(!xs.is_empty());xs.sort_by(f64::total_cmp);if xs.len()%2==1{xs[xs.len()/2]}else{(xs[xs.len()/2-1]+xs[xs.len()/2])/2.}}
fn gm(xs:&[f64])->f64{(xs.iter().map(|x|x.ln()).sum::<f64>()/xs.len()as f64).exp()}
fn ancestor(id:u64,events:&BTreeMap<u64,Event>,accept:impl Fn(&Event)->bool)->Option<u64>{let mut next=id;let mut depth=0;while next!=0{depth+=1;assert!(depth<64);let e=&events[&next];if accept(e){return Some(next);}next=e[1];}None}
fn graph(g:&Value,mode:&str,sample_ms:f64,raw:&mut BTreeMap<String,String>)->Value{let path=Path::new(g["file"].as_str().unwrap());let bytes=fs::read(path).unwrap();assert_eq!(bytes.len()%80,0);let n:usize=g["thread_lengths"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as usize).sum();assert_eq!(bytes.len(),n*80);let drops:u64=g["thread_dropped"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()).sum();raw.insert(path.display().to_string(),hash(path));let output=Command::new("gzip").args(["-c","--"]).arg(path).output().unwrap();assert!(output.status.success());let packed=path.with_extension("events.gz");fs::write(&packed,output.stdout).unwrap();let packed_sha=hash(&packed);if mode=="off"{assert_eq!(n,0);assert_eq!(drops,0);return json!({"round":g["round"],"events":0,"dropped":0,"mode":"off","packed":packed,"packed_sha256":packed_sha});}
 let mut events=BTreeMap::new();let mut offset=0;let mut workers_seen=BTreeSet::new();for count in g["thread_lengths"].as_array().unwrap(){let mut worker=None;for _ in 0..count.as_u64().unwrap(){let e:Event=core::array::from_fn(|i|u64::from_le_bytes(bytes[offset+i*8..offset+i*8+8].try_into().unwrap()));offset+=80;assert_eq!(e[0]>>32,e[7]);assert!(e[7]<g["thread_lengths"].as_array().unwrap().len()as u64);if let Some(id)=worker{assert_eq!(e[7],id);}else{assert!(workers_seen.insert(e[7]));worker=Some(e[7]);}assert!(e[6]>=e[5]&&e[6]>0);if e[8]!=0{assert!(e[9]>=e[8]);}assert!(events.insert(e[0],e).is_none());}}
 if drops>0{return json!({"round":g["round"],"events":n,"dropped":drops,"complete":false,"packed":packed,"packed_sha256":packed_sha});}
 for e in events.values(){if e[1]!=0{let parent=&events[&e[1]];assert!(parent[5]<=e[5]&&e[6]<=parent[6]);}}
 let apis:Vec<_>=events.values().filter(|e|e[2]==0).collect();assert_eq!(apis.len(),1);let api=apis[0];assert!((api[6]-api[5])as f64/1e6<=sample_ms+0.01);let mut serial_children:BTreeMap<u64,u64>=BTreeMap::new();for e in events.values().filter(|e|e[8]!=0){if let Some(id)=ancestor(e[1],&events,|p|p[8]!=0){let p=&events[&id];assert_eq!(e[7],p[7]);assert!(p[8]<=e[8]&&e[9]<=p[9]);*serial_children.entry(id).or_default()+=e[9]-e[8];}}
 let mut exclusive=BTreeMap::new();let mut by_kind:BTreeMap<u64,u64>=BTreeMap::new();for e in events.values().filter(|e|e[8]!=0){let duration=e[9]-e[8];let children=serial_children.get(&e[0]).copied().unwrap_or(0);assert!(duration>=children);let cpu=duration-children;exclusive.insert(e[0],cpu);*by_kind.entry(e[2]).or_default()+=cpu;}
 let mut queries=BTreeMap::new();let mut all_windows=Vec::new();for(name,query_kind,kernel_kind,window_kind)in [("a",6,1,10),("kh",2,2,11),("g2",5,3,12)]{let roots:Vec<_>=events.values().filter(|e|e[2]==query_kind).collect();assert_eq!(roots.len(),1,"query{name}");let root=roots[0];let kernels:Vec<_>=events.values().filter(|e|e[2]==kernel_kind).collect();assert_eq!(kernels.len(),1);let kernel=kernels[0];assert!(ancestor(kernel[0],&events,|e|e[0]==root[0]).is_some());let ready=if name=="g2"{let rs:Vec<_>=events.values().filter(|e|e[2]==4&&e[1]==kernel[0]).collect();assert_eq!(rs.len(),1);rs[0][6]}else{kernel[5]};let owned=|e:&Event|ancestor(e[0],&events,|p|p[0]==root[0]).is_some();let cpu:u64=events.values().filter(|e|owned(e)).map(|e|exclusive.get(&e[0]).copied().unwrap_or(0)).sum();let inverse_cpu:u64=events.values().filter(|e|owned(e)&&[40,41].contains(&e[2])).map(|e|exclusive.get(&e[0]).copied().unwrap_or(0)).sum();let mut windows=Vec::new();for e in events.values().filter(|e|e[2]==window_kind&&e[1]==kernel[0]){assert!(e[5]>=ready);let cpu:u64=events.values().filter(|x|ancestor(x[0],&events,|p|p[0]==e[0]).is_some()).map(|x|exclusive.get(&x[0]).copied().unwrap_or(0)).sum();let row=json!({"query":name,"window":e[3],"worker":e[7],"start_ms":e[5]as f64/1e6,"finish_ms":e[6]as f64/1e6,"input_available_to_start_ms":(e[5]-ready)as f64/1e6,"inclusive_elapsed_ms":(e[6]-e[5])as f64/1e6,"covered_serial_CPU_ms":cpu as f64/1e6});all_windows.push(row.clone());windows.push(row);}assert!(!windows.is_empty());windows.sort_by_key(|e|e["window"].as_u64().unwrap());let last=windows.iter().max_by(|a,b|a["finish_ms"].as_f64().partial_cmp(&b["finish_ms"].as_f64()).unwrap()).unwrap().clone();queries.insert(name,json!({"query_start_ms":root[5]as f64/1e6,"query_finish_ms":root[6]as f64/1e6,"query_elapsed_ms":(root[6]-root[5])as f64/1e6,"kernel_inputs_available_ms":ready as f64/1e6,"pre_kernel_elapsed_ms":(ready-root[5])as f64/1e6,"covered_serial_CPU_ms":cpu as f64/1e6,"covered_inverse_CPU_ms":inverse_cpu as f64/1e6,"windows":windows,"last_window":last}));}
 let last_query=queries.iter().max_by(|a,b|a.1["query_finish_ms"].as_f64().partial_cmp(&b.1["query_finish_ms"].as_f64()).unwrap()).unwrap().0.to_string();let total_cpu:u64=exclusive.values().sum();let owned_cpu:u64=queries.values().map(|q|(q["covered_serial_CPU_ms"].as_f64().unwrap()*1e6).round()as u64).sum();assert!(owned_cpu<=total_cpu+3);json!({"round":g["round"],"events":n,"dropped":0,"complete":true,"API_elapsed_ms":(api[6]-api[5])as f64/1e6,"queries":queries,"last_query":last_query,"covered_serial_CPU_ms":total_cpu as f64/1e6,"unattributed_serial_CPU_ms":total_cpu.saturating_sub(owned_cpu)as f64/1e6,"exclusive_CPU_ns_by_kind":by_kind,"windows":all_windows,"packed":packed,"packed_sha256":packed_sha})}
fn main(){let r=Path::new(R);assert_eq!(read(r.join("capture/result.json"))["status"],"complete");for(p,h)in read(r.join("capture-pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let mut ids:BTreeSet<String>=serde_json::from_value(read(r.join("prior-proofs.json"))).unwrap();assert_eq!(ids.len(),7205);let mut inventory=BTreeMap::new();let mut rows=Vec::new();let mut graphs=Vec::new();let mut raw=BTreeMap::new();for phase in ["preflight","capture"]{let jobs=read(r.join(if phase=="preflight"{"preflight-jobs.json"}else{"jobs.json"}));for job in jobs.as_array().unwrap(){let name=job["name"].as_str().unwrap();let output=Path::new(job["output"].as_str().unwrap());let proof=output.join("0.proof");let public=output.join("0.public");assert_eq!(fs::metadata(&proof).unwrap().len(),164);assert_eq!(hash(&public),job["public_sha256"].as_str().unwrap());assert!(ids.insert(hash(&proof)));for p in [proof,public]{inventory.insert(p.display().to_string(),hash(p));}let log=fs::read_to_string(r.join(phase).join(name).join("stdout.log")).unwrap();let summary:Value=serde_json::from_str(log.lines().find_map(|l|l.strip_prefix("SUMMARY ")).unwrap()).unwrap();assert_eq!(summary["rounds"],job["rounds"]);assert_eq!(summary["workers"],job["workers"]);assert_eq!(summary["priming"],3);let samples:Vec<f64>=log.lines().filter_map(|l|l.strip_prefix("SAMPLE ")).map(|l|serde_json::from_str::<Value>(l).unwrap()["ms"].as_f64().unwrap()).collect();assert_eq!(samples.len(),job["rounds"].as_u64().unwrap()as usize);let mode=job["mode"].as_str().unwrap();let gs:Vec<Value>=log.lines().filter_map(|l|l.strip_prefix("GRAPH ")).map(|l|serde_json::from_str(l).unwrap()).collect();assert_eq!(gs.len(),if mode=="accepted"{0}else if phase=="preflight"{1}else{3});let observations:Vec<Value>=log.lines().filter_map(|l|l.strip_prefix("EVENTS ")).map(|l|serde_json::from_str(l).unwrap()).collect();if mode!="accepted"{assert_eq!(observations.len(),samples.len());for o in &observations{if mode=="off"{assert_eq!(o["events"],0);assert_eq!(o["dropped"],0);}}}let verify=fs::read_to_string(r.join(format!("{phase}/verify-{name}/stdout.log"))).unwrap();assert!(verify.contains("verified 1 distinct proofs across 1 pinned keys"));for g in gs{let round=g["round"].as_u64().unwrap()as usize;assert!([0,samples.len()/2,samples.len()-1].contains(&round));graphs.push(json!({"phase":phase,"job":job,"graph":graph(&g,mode,samples[round],&mut raw)}));}rows.push(json!({"phase":phase,"job":job,"summary":summary,"samples_ms":samples,"median_ms":median(samples.clone()),"observations":observations}));}}
 assert_eq!(rows.len(),28);assert_eq!(inventory.len(),56);assert_eq!(ids.len(),7233);let mut cases=BTreeMap::new();let mut calibration=Vec::new();let mut overhead_failures=Vec::new();for workers in [16,32]{let mut modes=BTreeMap::new();for mode in ["accepted","off","on"]{let rs:Vec<_>=rows.iter().filter(|r|r["phase"]=="capture"&&r["job"]["workers"]==workers&&r["job"]["mode"]==mode).collect();assert_eq!(rs.len(),3);modes.insert(mode,json!({"ms":median(rs.iter().map(|r|r["median_ms"].as_f64().unwrap()).collect()),"CPU_ms_per_request":median(rs.iter().map(|r|(r["summary"]["user_cpu_ms"].as_f64().unwrap()+r["summary"]["system_cpu_ms"].as_f64().unwrap())/31.).collect()),"max_lifetime_RSS_mib":rs.iter().map(|r|r["summary"]["whole_process_maxrss_kib"].as_f64().unwrap()/1024.).fold(0.,f64::max)}));}let values=|a:&str,b:&str|->Vec<f64>{(0..3).map(|block|{let ms=|mode:&str|rows.iter().find(|r|r["phase"]=="capture"&&r["job"]["workers"]==workers&&r["job"]["block"]==block&&r["job"]["mode"]==mode).unwrap()["median_ms"].as_f64().unwrap();ms(a)/ms(b)}).collect()};let cal=values("off","accepted");for(block,x)in cal.iter().enumerate(){if !(1./1.05..=1.05).contains(x){calibration.push(format!("w{workers}b{block} OFF/accepted={x}"));}}if !(1./1.03..=1.03).contains(&median(cal.clone())){calibration.push(format!("w{workers} medianOFF/accepted={}",median(cal.clone())));}let onoff=values("on","off");if gm(&onoff)>1.10{overhead_failures.push(format!("w{workers} ON/OFF={}",gm(&onoff)));}cases.insert(workers.to_string(),json!({"modes":modes,"OFF_accepted_ratios":cal,"ON_OFF_ratios":onoff,"ON_OFF_geometric":gm(&onoff)}));}
 let complete=graphs.iter().filter(|g|g["graph"]["complete"]==true).count();let incomplete=graphs.iter().filter(|g|g["graph"]["complete"]==false).count();let mut aggregate=BTreeMap::new();for workers in [16,32]{let gs:Vec<_>=graphs.iter().filter(|g|g["phase"]=="capture"&&g["job"]["workers"]==workers&&g["graph"]["complete"]==true).collect();let mut counts=BTreeMap::new();for g in &gs{*counts.entry(g["graph"]["last_query"].as_str().unwrap()).or_insert(0)+=1;}let mut qs=BTreeMap::new();for name in ["a","kh","g2"]{if gs.is_empty(){continue;}let vals=|key:&str|gs.iter().map(|g|g["graph"]["queries"][name][key].as_f64().unwrap()).collect();let waits:Vec<f64>=gs.iter().flat_map(|g|g["graph"]["queries"][name]["windows"].as_array().unwrap().iter().map(|w|w["input_available_to_start_ms"].as_f64().unwrap())).collect();qs.insert(name,json!({"median_query_elapsed_ms":median(vals("query_elapsed_ms")),"median_covered_serial_CPU_ms":median(vals("covered_serial_CPU_ms")),"median_covered_inverse_CPU_ms":median(vals("covered_inverse_CPU_ms")),"median_pre_kernel_elapsed_ms":median(vals("pre_kernel_elapsed_ms")),"median_window_input_available_to_start_ms":median(waits.clone()),"max_window_input_available_to_start_ms":waits.iter().copied().fold(0.,f64::max)}));}aggregate.insert(workers.to_string(),json!({"complete_graphs":gs.len(),"last_query_counts":counts,"queries":qs}));}
 save(r.join("proof-inventory.json"),&json!(inventory));save(r.join("rows.json"),&json!(rows));save(r.join("graphs.json"),&json!(graphs));save(r.join("raw-local-sha256.json"),&json!(raw));save(r.join("analysis.json"),&json!({"cases":cases,"calibration_failures":calibration,"overhead_failures":overhead_failures,"low_overhead_qualified":calibration.is_empty()&&overhead_failures.is_empty(),"complete_enabled_graphs":complete,"incomplete_enabled_graphs":incomplete,"trace_aggregates":aggregate,"SDK_requests":652,"independent_gnark_exports":28,"proof_public_members":56,"next_prior_count":7233,"adopted":false,"goal_achieved":false}));println!("652SDK28Gnark;{}complete{}incompletegraphs;calibration{}overhead{};next7233",complete,incomplete,calibration.len(),overhead_failures.len());}
